input.content:
workspace "Bookshop" "A simple online bookshop" {
    model {
        customer = person "Customer" "A customer of the online bookshop"

        bookshop = softwareSystem "Bookshop" "An online bookshop for browsing and ordering books" {
            webStore = container "Web Store" "Lets customers browse the catalogue and place orders" "Java Spring"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Java"
        }

        customer -> webStore "Browses books and places orders" "HTTPS"
        webStore -> orderProcessor "Submits orders for processing" "HTTP"
    }

    views {
        systemContext bookshop "SystemContext" "System context for the Bookshop" {
            include *
            autoLayout
        }
    }
}

